mapper.select:
SELECT 
FROM historical_group_pull_member
WHERE tenant_id = #{tenantId}
  AND id = #{id}
LIMIT 1

mapper.update:
UPDATE historical_group_pull_member
SET contact_status = #{targetStatus},
    contact_error_code = #{errorCode},
    contact_error_message = #{errorMessage},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND contact_status = #{pendingStatus}

UPDATE historical_group_pull_member
SET add_status = #{targetStatus},
    add_error_code = #{errorCode},
    add_error_message = #{errorMessage},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND add_status = #{pendingStatus}

UPDATE historical_group_pull_member
SET send_status = #{sendingStatus},
    send_command_id = #{commandId},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND send_status = #{pendingStatus}
  AND send_command_id IS NULL

UPDATE historical_group_pull_member
SET send_status = #{failedStatus},
    send_error_code = #{row.sendErrorCode},
    send_error_message = #{row.sendErrorMessage},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND send_status = #{pendingStatus}
  AND send_command_id IS NULL

UPDATE historical_group_pull_member
SET send_status = #{failedStatus},
    send_error_code = #{row.sendErrorCode},
    send_error_message = #{row.sendErrorMessage},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND send_command_id = #{row.sendCommandId}
  AND send_status = #{sendingStatus}
  AND send_result_event_id IS NULL

UPDATE historical_group_pull_member
SET send_status = #{row.sendStatus},
    send_result_event_id = #{row.sendResultEventId},
    send_error_code = #{row.sendErrorCode},
    send_error_message = #{row.sendErrorMessage},
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND execution_id = #{row.executionId}
  AND send_command_id = #{row.sendCommandId}
  AND send_status = #{sendingStatus}
  AND send_result_event_id IS NULL

UPDATE historical_group_pull_member
SET send_status = #{targetStatus},
    send_result_event_id = #{eventId},
    send_error_code = #{errorCode},
    send_error_message = #{errorMessage},
    updated_at = #{updatedAt}
WHERE send_command_id = #{commandId}
  AND send_status = #{sendingStatus}
  AND send_result_event_id IS NULL
